import base64

# 코드를 텍스트가 아닌 암호문으로 담아서 터미널 씹힘을 방지합니다.
sidebar_b64 = '({'

def write_file(path, b64_str):
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64_str))

write_file('src/components/NAS/Window/SidebarTree.js', sidebar_b64)
print("SUCCESS: File written without terminal mangling.")
